Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Definition wr4 (m : word -> option byte) (a v : Z) : word -> option byte := wbytes m (Z_to_bv 64 a) (word_to_le_bytes 4 (Z_to_bv 64 v)).
(* [comment removed for export] *)
Definition SFZ (m : word -> option byte) (a1 a2 a3 a4 : Z) : word -> option byte := wr4 (wr4 (wr4 (wr4 m a4 0) a3 0) a2 0) a1 0.
Definition SFA (m : word -> option byte) (s a1 a2 a3 a4 : Z) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (SFZ m a1 a2 a3 a4)
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 20)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 21)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (getr regs 22)))
    (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (getr regs 23)))
    (Z_to_bv 64 (s - 72)) (word_to_le_bytes 8 (getr regs 24)).
(* [comment removed for export] *)
Definition SFR (m : word -> option byte) (a1 a2 a3 a4 y0 y1 y2 y3 : Z) : word -> option byte := wr4 (wr4 (wr4 (wr4 m a1 y0) a2 y1) a3 y2) a4 y3.

Section Segs.
Context {fx : FPState}.
Ltac grows := repeat (eapply mem_grows_trans; [|apply wbytes_grows]); apply mem_grows_refl.
Variable rom : word -> option byte.
Ltac condS := pin; rewrite ?c_lts_Zs by lia; first [ apply Z.ltb_lt | apply Z.ltb_ge ]; lia.
Ltac fixv' v tac := lazymatch goal with |- msteps _ (mkst (regupd _ _ ?x) _ _ _) _ => first [ constr_eq x v | replace x with v by (symmetry; tac) ] end.
#[local] Notation K := 10000%Z (only parsing).
#[local] Notation inb x := (- K <= x <= K)%Z (only parsing).
#[local] Notation inm x := (0 <= x <= K)%Z (only parsing).

(* [comment removed for export] *)
Lemma sf_c50 : forall regs m (icy x3 : Z), inb icy -> inm x3 ->
  getr regs 20 = Z_to_bv 64 icy -> getr regs 15 = Z_to_bv 64 x3 ->
  exists regs', msteps SEGS (mkst regs (0x92ca8 : word) m rom) (mkst regs' (0x92c68 : word) m rom)
    /\ getr regs' 15 = Z_to_bv 64 (Z.max x3 icy) /\ regs_agree (fun r => In r [15]%list) regs regs'.
