Lemma sf_c38 : forall regs m (jcx icy x3 : Z), inb jcx -> inb icy -> inm x3 ->
  getr regs 23 = Z_to_bv 64 jcx -> getr regs 20 = Z_to_bv 64 icy -> getr regs 15 = Z_to_bv 64 x3 ->
  exists regs', msteps SEGS (mkst regs (0x92c90 : word) m rom) (mkst regs' (0x92c68 : word) m rom)
    /\ getr regs' 16 = Z_to_bv 64 jcx /\ getr regs' 15 = Z_to_bv 64 (Z.max x3 icy) /\ regs_agree (fun r => In r [15; 16]%list) regs regs'.
