Lemma sf_c34 : forall regs m (jcx icy x2 x3 : Z), inb jcx -> inb icy -> inm x2 -> inm x3 ->
  getr regs 23 = Z_to_bv 64 jcx -> getr regs 20 = Z_to_bv 64 icy -> getr regs 16 = Z_to_bv 64 x2 -> getr regs 15 = Z_to_bv 64 x3 ->
  exists regs', msteps SEGS (mkst regs (0x92c8c : word) m rom) (mkst regs' (0x92c68 : word) m rom)
    /\ getr regs' 16 = Z_to_bv 64 (Z.max x2 jcx) /\ getr regs' 15 = Z_to_bv 64 (Z.max x3 icy) /\ regs_agree (fun r => In r [15; 16]%list) regs regs'.
