(* [comment removed for export] *)
Lemma sfmt_E : forall regs m (p cxj cyi jcx icy x0 x1 x2 x3 : Z) (bs : list byte),
  rdn SEGS m (Z_to_bv 64 p) 4 = Some bs -> length bs = 4%nat ->
  inb cxj -> inb cyi -> inb jcx -> inb icy -> inm x0 -> inm x1 -> inm x2 -> inm x3 ->
  getr regs 18 = Z_to_bv 64 p -> getr regs 22 = Z_to_bv 64 cxj -> getr regs 19 = Z_to_bv 64 cyi ->
  getr regs 23 = Z_to_bv 64 jcx -> getr regs 20 = Z_to_bv 64 icy ->
  getr regs 5 = Z_to_bv 64 x0 -> getr regs 17 = Z_to_bv 64 x1 -> getr regs 16 = Z_to_bv 64 x2 -> getr regs 15 = Z_to_bv 64 x3 ->
  getr regs 9 = Z_to_bv 64 1 ->
  exists regs' y0 y1 y2 y3,
    msteps SEGS (mkst regs (0x92c78 : word) m rom) (mkst regs' (0x92c68 : word) m rom)
    /\ inm y0 /\ inm y1 /\ inm y2 /\ inm y3
    /\ getr regs' 5 = Z_to_bv 64 y0 /\ getr regs' 17 = Z_to_bv 64 y1 /\ getr regs' 16 = Z_to_bv 64 y2 /\ getr regs' 15 = Z_to_bv 64 y3
    /\ regs_agree (fun r => In r [5; 15; 16; 17; 24]%list) regs regs'.
