(* [comment removed for export] *)
Lemma sfmt_N : forall regs m (p cxj jcx rend : Z), (0 <= p)%Z -> (p + 4 <= rend < 2 ^ 64)%Z -> inb cxj -> inb jcx ->
  getr regs 18 = Z_to_bv 64 p -> getr regs 22 = Z_to_bv 64 cxj -> getr regs 23 = Z_to_bv 64 jcx -> getr regs 21 = Z_to_bv 64 rend ->
  exists regs', msteps SEGS (mkst regs (0x92c68 : word) m rom) (mkst regs' (if Z.eq_dec (p + 4) rend then (0x92c34 : word) else (0x92c78 : word)) m rom)
    /\ getr regs' 18 = Z_to_bv 64 (p + 4) /\ getr regs' 22 = Z_to_bv 64 (cxj - 1) /\ getr regs' 23 = Z_to_bv 64 (jcx + 1)
    /\ regs_agree (fun r => In r [18; 22; 23]%list) regs regs'.
