(* [comment removed for export] *)
Lemma sfmt_row : forall (n : nat) regs m (row j sx cx cyi icy x0 x1 x2 x3 : Z),
  (0 <= row)%Z -> (row + 4 * sx < 2 ^ 64)%Z -> (0 <= j)%Z -> (j + Z.of_nat n = sx - 1)%Z -> (sx <= K)%Z -> (0 <= cx <= K)%Z ->
  inb cyi -> inb icy -> inm x0 -> inm x1 -> inm x2 -> inm x3 ->
  (forall j', (j <= j' < sx)%Z -> exists bs, rdn SEGS m (Z_to_bv 64 (row + 4 * j')) 4 = Some bs /\ length bs = 4%nat) ->
  getr regs 18 = Z_to_bv 64 (row + 4 * j) -> getr regs 22 = Z_to_bv 64 (cx - j) -> getr regs 19 = Z_to_bv 64 cyi ->
  getr regs 23 = Z_to_bv 64 (j - cx) -> getr regs 20 = Z_to_bv 64 icy -> getr regs 21 = Z_to_bv 64 (row + 4 * sx) ->
  getr regs 5 = Z_to_bv 64 x0 -> getr regs 17 = Z_to_bv 64 x1 -> getr regs 16 = Z_to_bv 64 x2 -> getr regs 15 = Z_to_bv 64 x3 ->
  getr regs 9 = Z_to_bv 64 1 ->
  exists regs' y0 y1 y2 y3,
    msteps SEGS (mkst regs (0x92c78 : word) m rom) (mkst regs' (0x92c34 : word) m rom)
    /\ inm y0 /\ inm y1 /\ inm y2 /\ inm y3
    /\ getr regs' 5 = Z_to_bv 64 y0 /\ getr regs' 17 = Z_to_bv 64 y1 /\ getr regs' 16 = Z_to_bv 64 y2 /\ getr regs' 15 = Z_to_bv 64 y3
    /\ regs_agree (fun r => In r [5; 15; 16; 17; 18; 22; 23; 24]%list) regs regs'.
