(* [comment removed for export] *)
Lemma sfmt_R : forall regs m (sel data row i sx cx cy : Z),
  (0 <= sel)%Z -> (sel + 16 + 8 <= 2 ^ 64)%Z -> (0 <= data)%Z -> (data + 8 * i + 8 <= 2 ^ 64)%Z -> (0 <= row)%Z -> (row + 4 * sx < 2 ^ 64)%Z ->
  (0 <= i <= K)%Z -> (1 <= sx <= K)%Z -> (0 <= cx <= K)%Z -> (0 <= cy <= K)%Z ->
  rdn SEGS m (Z_to_bv 64 (sel + 16)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 data)) ->
  rdn SEGS m (Z_to_bv 64 (data + 8 * i)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 row)) ->
  getr regs 10 = Z_to_bv 64 sel -> getr regs 7 = Z_to_bv 64 i -> getr regs 30 = Z_to_bv 64 sx -> getr regs 8 = Z_to_bv 64 (4 * sx) ->
  getr regs 28 = Z_to_bv 64 cx -> getr regs 29 = Z_to_bv 64 cy -> getr regs 31 = Z_to_bv 64 (- cx) ->
  exists regs', msteps SEGS (mkst regs (0x92c3c : word) m rom) (mkst regs' (0x92c78 : word) m rom)
    /\ getr regs' 18 = Z_to_bv 64 (row + 4 * 0) /\ getr regs' 22 = Z_to_bv 64 (cx - 0) /\ getr regs' 19 = Z_to_bv 64 (cy - i)
    /\ getr regs' 23 = Z_to_bv 64 (0 - cx) /\ getr regs' 20 = Z_to_bv 64 (i - cy) /\ getr regs' 21 = Z_to_bv 64 (row + 4 * sx)
    /\ regs_agree (fun r => In r [18; 19; 20; 21; 22; 23]%list) regs regs'.
Proof.
