Lemma sfmt_Ri : forall regs m (i sy : Z), (0 <= i < sy)%Z -> (sy <= K)%Z ->
  getr regs 7 = Z_to_bv 64 i -> getr regs 6 = Z_to_bv 64 sy ->
  exists regs', msteps SEGS (mkst regs (0x92c34 : word) m rom) (mkst regs' (if Z.eq_dec (i + 1) sy then (0x92ce0 : word) else (0x92c3c : word)) m rom)
    /\ getr regs' 7 = Z_to_bv 64 (i + 1) /\ regs_agree (fun r => In r [7]%list) regs regs'.
