Ltac sok_in SOK :=
  store_ok_peel;
  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

(* [comment removed for export] *)
Lemma sfmt_A : forall regs m (s sel a1 a2 a3 a4 sy sx cy cx data name : Z),
  (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= sel)%Z -> RECat m sel (sel_flds sy sx cy cx data name) ->
  (1 <= sy <= K)%Z -> (1 <= sx <= K)%Z -> (0 <= cx < sx)%Z -> (0 <= cy < sy)%Z ->
  (1 <= a1)%Z -> (a1 + 4 < 2 ^ 64)%Z -> (1 <= a2)%Z -> (a2 + 4 < 2 ^ 64)%Z -> (1 <= a3)%Z -> (a3 + 4 < 2 ^ 64)%Z -> (1 <= a4)%Z -> (a4 + 4 < 2 ^ 64)%Z ->
  (sel + 32 <= a1 \/ a1 + 4 <= sel)%Z -> (sel + 32 <= a2 \/ a2 + 4 <= sel)%Z -> (sel + 32 <= a3 \/ a3 + 4 <= sel)%Z -> (sel + 32 <= a4 \/ a4 + 4 <= sel)%Z ->
  (sel + 32 <= s - 80 \/ s <= sel)%Z ->
  store_ok SEGS m (Z_to_bv 64 a1) 4 = true -> store_ok SEGS m (Z_to_bv 64 a2) 4 = true ->
  store_ok SEGS m (Z_to_bv 64 a3) 4 = true -> store_ok SEGS m (Z_to_bv 64 a4) 4 = true ->
  store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 10 = Z_to_bv 64 sel ->
  getr regs 11 = Z_to_bv 64 a1 -> getr regs 12 = Z_to_bv 64 a2 -> getr regs 13 = Z_to_bv 64 a3 -> getr regs 14 = Z_to_bv 64 a4 ->
  exists regs',
    msteps SEGS (mkst regs (0x92bac : word) m rom) (mkst regs' (0x92c3c : word) (SFA m s a1 a2 a3 a4 regs) rom)
    /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 10 = Z_to_bv 64 sel /\ getr regs' 7 = Z_to_bv 64 0 /\ getr regs' 30 = Z_to_bv 64 sx
    /\ getr regs' 8 = Z_to_bv 64 (4 * sx) /\ getr regs' 28 = Z_to_bv 64 cx /\ getr regs' 29 = Z_to_bv 64 cy /\ getr regs' 31 = Z_to_bv 64 (- cx)
    /\ getr regs' 6 = Z_to_bv 64 sy /\ getr regs' 9 = Z_to_bv 64 1
    /\ getr regs' 5 = Z_to_bv 64 0 /\ getr regs' 17 = Z_to_bv 64 0 /\ getr regs' 16 = Z_to_bv 64 0 /\ getr regs' 15 = Z_to_bv 64 0
