(* [comment removed for export] *)
Lemma sfmt_Z : forall regs mi (s a1 a2 a3 a4 y0 y1 y2 y3 : Z) (ret v0 v1 v2 v3 v4 v5 v6 v7 v8 : word),
  (80 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> inm y0 -> inm y1 -> inm y2 -> inm y3 ->
  rdn SEGS mi (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 v0) -> rdn SEGS mi (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 v1) ->
  rdn SEGS mi (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 v2) -> rdn SEGS mi (Z_to_bv 64 (s - 32)) 8 = Some (word_to_le_bytes 8 v3) ->
  rdn SEGS mi (Z_to_bv 64 (s - 40)) 8 = Some (word_to_le_bytes 8 v4) -> rdn SEGS mi (Z_to_bv 64 (s - 48)) 8 = Some (word_to_le_bytes 8 v5) ->
  rdn SEGS mi (Z_to_bv 64 (s - 56)) 8 = Some (word_to_le_bytes 8 v6) -> rdn SEGS mi (Z_to_bv 64 (s - 64)) 8 = Some (word_to_le_bytes 8 v7) ->
  rdn SEGS mi (Z_to_bv 64 (s - 72)) 8 = Some (word_to_le_bytes 8 v8) ->
  (1 <= a1)%Z -> (a1 + 4 < 2 ^ 64)%Z -> (1 <= a2)%Z -> (a2 + 4 < 2 ^ 64)%Z -> (1 <= a3)%Z -> (a3 + 4 < 2 ^ 64)%Z -> (1 <= a4)%Z -> (a4 + 4 < 2 ^ 64)%Z ->
  store_ok SEGS mi (Z_to_bv 64 a1) 4 = true -> store_ok SEGS mi (Z_to_bv 64 a2) 4 = true ->
  store_ok SEGS mi (Z_to_bv 64 a3) 4 = true -> store_ok SEGS mi (Z_to_bv 64 a4) 4 = true ->
  getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 1 = ret ->
  getr regs 11 = Z_to_bv 64 a1 -> getr regs 12 = Z_to_bv 64 a2 -> getr regs 13 = Z_to_bv 64 a3 -> getr regs 14 = Z_to_bv 64 a4 ->
  getr regs 5 = Z_to_bv 64 y0 -> getr regs 17 = Z_to_bv 64 y1 -> getr regs 16 = Z_to_bv 64 y2 -> getr regs 15 = Z_to_bv 64 y3 ->
  exists regs',
    msteps SEGS (mkst regs (0x92ce0 : word) mi rom) (mkst regs' ret (SFR mi a1 a2 a3 a4 y0 y1 y2 y3) rom)
    /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 8 = v0 /\ getr regs' 9 = v1 /\ getr regs' 18 = v2
    /\ getr regs' 19 = v3 /\ getr regs' 20 = v4 /\ getr regs' 21 = v5 /\ getr regs' 22 = v6 /\ getr regs' 23 = v7 /\ getr regs' 24 = v8
    /\ regs_agree (fun r => In r [2; 8; 9; 10; 18; 19; 20; 21; 22; 23; 24]%list) regs regs'.
Proof.
