Lemma SFA_rdn : forall m s a1 a2 a3 a4 regs (b : Z) (n : nat), (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= b)%Z -> (b + Z.of_nat n < 2 ^ 64)%Z ->
