  (b + Z.of_nat n <= a1 \/ a1 + 4 <= b)%Z -> (b + Z.of_nat n <= a2 \/ a2 + 4 <= b)%Z -> (b + Z.of_nat n <= a3 \/ a3 + 4 <= b)%Z ->
  (b + Z.of_nat n <= a4 \/ a4 + 4 <= b)%Z -> (b + Z.of_nat n <= s - 80 \/ s <= b)%Z ->
  rdn SEGS (SFA m s a1 a2 a3 a4 regs) (Z_to_bv 64 b) n = rdn SEGS m (Z_to_bv 64 b) n.
