(* [comment removed for export] *)
Theorem sfmt_run : forall regs m (s sel a1 a2 a3 a4 sy sx cy cx data name : Z) (rows : Z -> Z) (ret : word),
  (80 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> (1 <= sel)%Z -> RECat m sel (sel_flds sy sx cy cx data name) ->
  (1 <= sy <= K)%Z -> (1 <= sx <= K)%Z -> (0 <= cx < sx)%Z -> (0 <= cy < sy)%Z ->
  (1 <= a1)%Z -> (a1 + 4 < 2 ^ 64)%Z -> (1 <= a2)%Z -> (a2 + 4 < 2 ^ 64)%Z -> (1 <= a3)%Z -> (a3 + 4 < 2 ^ 64)%Z -> (1 <= a4)%Z -> (a4 + 4 < 2 ^ 64)%Z ->
  (sel + 32 <= a1 \/ a1 + 4 <= sel)%Z -> (sel + 32 <= a2 \/ a2 + 4 <= sel)%Z -> (sel + 32 <= a3 \/ a3 + 4 <= sel)%Z -> (sel + 32 <= a4 \/ a4 + 4 <= sel)%Z ->
  (sel + 32 <= s - 80 \/ s <= sel)%Z ->
  store_ok SEGS m (Z_to_bv 64 a1) 4 = true -> store_ok SEGS m (Z_to_bv 64 a2) 4 = true ->
  store_ok SEGS m (Z_to_bv 64 a3) 4 = true -> store_ok SEGS m (Z_to_bv 64 a4) 4 = true ->
  store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
  (0 <= data)%Z -> (data + 8 * sy < 2 ^ 64)%Z ->
  (data + 8 * sy <= a1 \/ a1 + 4 <= data)%Z -> (data + 8 * sy <= a2 \/ a2 + 4 <= data)%Z -> (data + 8 * sy <= a3 \/ a3 + 4 <= data)%Z ->
  (data + 8 * sy <= a4 \/ a4 + 4 <= data)%Z -> (data + 8 * sy <= s - 80 \/ s <= data)%Z ->
  (forall i', (0 <= i' < sy)%Z ->
     (0 <= rows i')%Z /\ (rows i' + 4 * sx < 2 ^ 64)%Z /\
     rdn SEGS m (Z_to_bv 64 (data + 8 * i')) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (rows i'))) /\
     (rows i' + 4 * sx <= a1 \/ a1 + 4 <= rows i')%Z /\ (rows i' + 4 * sx <= a2 \/ a2 + 4 <= rows i')%Z /\
     (rows i' + 4 * sx <= a3 \/ a3 + 4 <= rows i')%Z /\ (rows i' + 4 * sx <= a4 \/ a4 + 4 <= rows i')%Z /\
     (rows i' + 4 * sx <= s - 80 \/ s <= rows i')%Z /\
     (forall j', (0 <= j' < sx)%Z -> exists bs, rdn SEGS m (Z_to_bv 64 (rows i' + 4 * j')) 4 = Some bs /\ length bs = 4%nat)) ->
  getr regs 1 = ret -> getr regs 2 = Z_to_bv 64 s -> getr regs 10 = Z_to_bv 64 sel ->
  getr regs 11 = Z_to_bv 64 a1 -> getr regs 12 = Z_to_bv 64 a2 -> getr regs 13 = Z_to_bv 64 a3 -> getr regs 14 = Z_to_bv 64 a4 ->
  exists regs' y0 y1 y2 y3,
    msteps SEGS (mkst regs (0x92bac : word) m rom) (mkst regs' ret (SFR (SFA m s a1 a2 a3 a4 regs) a1 a2 a3 a4 y0 y1 y2 y3) rom)
    /\ inm y0 /\ inm y1 /\ inm y2 /\ inm y3
    /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 1 = ret
    /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9 /\ getr regs' 18 = getr regs 18 /\ getr regs' 19 = getr regs 19
    /\ getr regs' 20 = getr regs 20 /\ getr regs' 21 = getr regs 21 /\ getr regs' 22 = getr regs 22 /\ getr regs' 23 = getr regs 23
    /\ getr regs' 24 = getr regs 24 /\ getr regs' 25 = getr regs 25 /\ getr regs' 26 = getr regs 26 /\ getr regs' 27 = getr regs 27
    /\ getr regs' 3 = getr regs 3 /\ getr regs' 4 = getr regs 4.
