Lemma SF_out : forall m s a1 a2 a3 a4 regs y0 y1 y2 y3 (x : word), (80 <= s)%Z -> (s < 2 ^ 64)%Z ->
  (0 <= a1)%Z -> (a1 + 4 < 2 ^ 64)%Z -> (0 <= a2)%Z -> (a2 + 4 < 2 ^ 64)%Z -> (0 <= a3)%Z -> (a3 + 4 < 2 ^ 64)%Z -> (0 <= a4)%Z -> (a4 + 4 < 2 ^ 64)%Z ->
  ~ (s - 80 <= bv_unsigned x < s)%Z ->
